theorem Erdos423.IsHofstadterSeq_card_omitted_Icc_eq_sub {a : Nat → Nat} (ha : Erdos423.IsHofstadterSeq a) {n : Nat}
  (hn : LE.le 1 n) :
  Eq (Finset.card (SDiff.sdiff (Finset.Icc 1 (a n)) (Finset.image a (Finset.Icc 1 n)))) (HSub.hSub (a n) n)

theorem Erdos423.IsHofstadterSeq_exists_ge_three_eq_iff_isGlobalConsecutiveBlockSum {a : Nat → Nat}
  (ha : Erdos423.IsHofstadterSeq a) (m : Nat) :
  Iff (Exists fun k => And (LE.le 3 k) (Eq (a k) m)) (Erdos423.IsGlobalConsecutiveBlockSum a m)
